SELECT EXISTS (
    SELECT 1
    FROM borrow_records
    WHERE borrow_id = #{borrowId}
)

SELECT EXISTS (
    SELECT 1
    FROM borrow_records
    WHERE book_id = #{bookId}
      AND return_date IS NULL
)

SELECT EXISTS (
    SELECT 1
    FROM borrow_records
    WHERE borrow_id = #{borrowId}
      AND return_date IS NOT NULL
)
